for (const line of outstanding) buckets[line.bucket] += line.outstandingCents;
return {
  customerId,
  asOf,
  lines,
  paging,
  buckets,
  totalOutstandingCents: outstanding.reduce((sum, line) => sum + line.outstandingCents, 0),
